class ChromeBrowser:
    def __init__(self):
        self.profile = None
        self.port = None
        self.process = None
        self.ws = None
        self._launch()

    def _launch(self):
        self.profile = tempfile.mkdtemp(prefix="opensurvey-chrome-")
        sock = socket.socket()
        sock.bind(("127.0.0.1", 0))
        self.port = sock.getsockname()[1]
        sock.close()
        self.process = subprocess.Popen(
            [CHROME, "--headless=new", "--disable-gpu", "--no-sandbox",
             "--no-first-run", "--no-default-browser-check",
             f"--remote-debugging-port={self.port}",
             f"--user-data-dir={self.profile}", "about:blank"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        info = None
        for _ in range(100):
            try:
                with urllib.request.urlopen(
                        f"http://127.0.0.1:{self.port}/json/version", timeout=1) as resp:
                    info = json.loads(resp.read())
                break
            except OSError:
                time.sleep(0.1)
        if info is None:
            raise RuntimeError("Chrome 调试端口未就绪")
        self.ws = WebSocket(info["webSocketDebuggerUrl"])

    def _shutdown(self):
        if self.process is not None:
            try:
                self.process.terminate()
                self.process.wait(timeout=5)
            except Exception:
                self.process.kill()
            self.process = None
        if self.ws is not None:
            self.ws.close()
            self.ws = None
        if self.profile is not None:
            shutil.rmtree(self.profile, ignore_errors=True)
            self.profile = None

    def restart(self):
        # 共享主机上 Chrome 偶发整体卡住：新标签页迟迟创建不出来，且同一浏览器
        # 进程内不再恢复；重启整个浏览器即可恢复（每个用例都在全新标签页开始，
        # 重启不丢失任何用例状态）。
        self._shutdown()
        self._launch()

    def new_page(self):
        try:
            return self._new_page()
        except TimeoutError:
            self.restart()
            return self._new_page()

    def _new_page(self):
        result = self.ws.call("Target.createTarget", {"url": "about:blank"}, timeout=30)
        target_id = result["targetId"]
        result = self.ws.call(
            "Target.attachToTarget", {"targetId": target_id, "flatten": True},
            timeout=30)
        page = ChromePage(self.ws, target_id, result["sessionId"])
        page.prepare()
        return page

    def close(self):
        self._shutdown()

